#!/usr/bin/env bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# End-to-end test of the fastbox kit with fakes only (fake monerod, fake peer, tiny fake snapshots, fake sudo/cpupower).
# Touches only test/w. Prints PASS/FAIL per case and "N PASS, M FAIL"; exit 1 on any FAIL.
set -u
here=$(cd "$(dirname "$0")" && pwd); KIT=$here/..; W=$here/w
rm -rf "${W:?}"; mkdir -p "$W/bin" "$W/nosudo" "$W/out" "$W/snapH/testnet/lmdb" "$W/snapS/testnet/lmdb"
{ printf '3105401\n'; head -c 30000 /dev/zero; } > "$W/snapH/testnet/lmdb/data.mdb"
{ printf '3106701\n'; head -c 20000 /dev/zero; } > "$W/snapS/testnet/lmdb/data.mdb"
HSZ=$(stat -c %s "$W/snapH/testnet/lmdb/data.mdb"); SSZ=$(stat -c %s "$W/snapS/testnet/lmdb/data.mdb")
cp "$here/fake_monerod.py" "$W/bin/monerod_S"; cp "$here/fake_monerod.py" "$W/bin/monerod_E"; echo "# E" >> "$W/bin/monerod_E"
chmod +x "$W"/bin/*
printf '#!/bin/sh\necho "sudo $*" >> "$FAKE_SUDO_LOG"; exit 0\n' > "$W/bin/sudo"
printf '#!/bin/sh\nexit 0\n' > "$W/bin/cpupower"
printf '#!/bin/sh\nexit 1\n' > "$W/nosudo/sudo"
chmod +x "$W"/bin/* "$W"/nosudo/sudo
echo schedutil > "$W/gov"
export PATH=$W/bin:$PATH FAKE_SUDO_LOG=$W/sudo.log GOV_FILE=$W/gov FAKE_ARGS_LOG=$W/args.log FAKE_CALLS_LOG=$W/calls.log
export FAKE_VERSION="Monero 'Fake' (v0.19.0.0-test)" FAKE_RATE=50 FAKE_WARM=1
export P2P_PORT=38390 RPC_PORT=38391 PEER=127.0.0.1:38393 PEER_RPC=127.0.0.1:38392 DD=$W/dd IDLE_S=1 SETTLE_S=0
export END_HEAVY=3105420 END_SMALL=3106720 TIMEOUT_HEAVY=60 TIMEOUT_SMALL=60
export BIN_S=$W/bin/monerod_S BIN_E=$W/bin/monerod_E SNAP_HEAVY=$W/snapH SNAP_SMALL=$W/snapS
pass=0; fail=0
check() { if eval "$2"; then echo "PASS $1"; pass=$((pass + 1)); else echo "FAIL $1"; fail=$((fail + 1)); fi; }
PIDS=()
cleanup() { for p in "${PIDS[@]}"; do kill "$p" 2>/dev/null; done; }
trap cleanup EXIT
startpeer() { python3 "$W/bin/monerod_S" --peer --rpc-bind-port 38392 --peer-port 38393 & PIDS+=($!); sleep 1; }
startpeer

# 1. full stage run: THREADS "default 4", 2 rounds, fake sudo that works, fake local peer with a readable PID
export OUT_BASE=$W/out/main THREADS="default 4" ROUNDS=2
mkdir -p "$DD"; touch "$DD/.fastbox_scratch"; echo old > "$DD/stale"
: > "$FAKE_SUDO_LOG"
bash "$KIT/fb_stage.sh" > "$W/main.out" 2>&1; rc=$?
SL=$OUT_BASE/stage.log
HDR="round,arm,start_h,end_h,blocks,wall_s,peak_anon_MB,peak_privdirty_MB,peak_rss_MB,read_MB,write_MB,tip_height,hash_match,post_idle_anon_MB,cpu_s,peer_cpu_s"
check "1 stage exit 0" '[ "$rc" = 0 ]'
check "1 FASTBOX_DONE is the last line (not abort)" 'tail -1 "$SL" | grep -qE "^FASTBOX_DONE [0-9]" '
check "1 stage.log has sha256, version, nproc, cpu, mem" 'grep -q "sha256=[0-9a-f]\{16\} version: Monero .Fake. (v0.19.0.0-test)" "$SL" && grep -q "nproc=" "$SL" && grep -q "mem_free_MB=" "$SL"'
for d in heavy_default heavy_4 small_default small_4; do
  f=$OUT_BASE/$d/results.csv
  check "1 $d header and 4 rows (2 arms x 2 rounds)" '[ "$(head -1 "$f")" = "$HDR" ] && [ "$(tail -n +2 "$f" | wc -l)" = 4 ] && [ "$(tail -n +2 "$f" | awk -F, "NF==16" | wc -l)" = 4 ]'
  check "1 $d alternating order S E / E S" '[ "$(tail -n +2 "$f" | cut -d, -f1,2 | tr "\n" " ")" = "1,S 1,E 2,E 2,S " ]'
  check "1 $d hash_match yes everywhere" '[ "$(tail -n +2 "$f" | cut -d, -f13 | sort -u)" = yes ]'
  check "1 $d AB_COMPLETE last line" '[ "$(tail -1 "$OUT_BASE/$d/summary.txt")" = AB_COMPLETE ]'
  check "1 $d reached its END" '[ "$(tail -n +2 "$f" | cut -d, -f4 | sort -n | head -1)" -ge "$([ "${d%%_*}" = heavy ] && echo $END_HEAVY || echo $END_SMALL)" ]'
done
check "1 summary has load average and other-monerod count per run" '[ "$(grep -c "loadavg=.*other_monerod_procs=[0-9]" "$OUT_BASE/heavy_4/summary.txt")" = 4 ]'
check "1 summary has copy time and size match" 'grep -q "copied snapshot: $HSZ bytes (size matches) in [0-9.]* s" "$OUT_BASE/heavy_default/summary.txt" && grep -q "copied snapshot: $SSZ bytes" "$OUT_BASE/small_4/summary.txt"'
check "1 copy-before-run: every node start saw the snapshot-size data.mdb" 'cut -d= -f2 <(grep -v -- "--offline" "$FAKE_ARGS_LOG" | grep -o "mdb_size=.*") | sort -u | tr "\n" " " | grep -qx "$SSZ $HSZ \|$HSZ $SSZ " ; [ "$(grep -v -- --offline "$FAKE_ARGS_LOG" | grep -c "mdb_size=\($HSZ\|$SSZ\)$")" = 16 ]'
check "1 stale file in DD was removed, marker present" '[ ! -e "$DD/stale" ] && [ -f "$DD/.fastbox_scratch" ]'
check "1 node command line: exclusive peer, ports, no-zmq, no-igd, no DNS checkpoints, no update checks" 'grep -v -- --offline "$FAKE_ARGS_LOG" | head -1 | grep -q -- "--testnet --data-dir $DD --add-exclusive-node $PEER --p2p-bind-ip 127.0.0.1 --p2p-bind-port 38390 --rpc-bind-ip 127.0.0.1 --rpc-bind-port 38391 --no-zmq --no-igd --non-interactive --disable-dns-checkpoints --check-updates disabled --log-file"'
check "1 --max-concurrency 4 on exactly 8 of 16 runs" '[ "$(grep -v -- --offline "$FAKE_ARGS_LOG" | grep -c -- "--max-concurrency 4 ")" = 8 ] && [ "$(grep -c -- "--max-concurrency 16" "$FAKE_ARGS_LOG")" = 0 ]'
check "1 heavy runs (all 8) pass --block-sync-size 5, small runs (all 8) do not" '[ "$(grep -v -- --offline "$FAKE_ARGS_LOG" | grep "mdb_size=$HSZ$" | grep -c -- "--block-sync-size 5")" = 8 ] && [ "$(grep -v -- --offline "$FAKE_ARGS_LOG" | grep "mdb_size=$SSZ$" | grep -c -- "--block-sync-size")" = 0 ]'
check "1 stage log records heavy_extra" 'grep -q "heavy_extra=\[--block-sync-size 5\]" "$OUT_BASE/stage.log"'
check "1 tip check offline with --no-zmq and our ports" 'grep -- --offline "$FAKE_ARGS_LOG" | head -1 | grep -q -- "--no-zmq.*--rpc-bind-port 38391"'
check "1 set_bans uses the host part of PEER (127.0.0.1), ban then unban" 'grep -q "^set_bans 127.0.0.1 True" "$W/calls.log" && grep -q "^set_bans 127.0.0.1 False" "$W/calls.log"'
check "1 peer_cpu_s numeric (local peer PID readable)" '[ "$(tail -n +2 "$OUT_BASE/heavy_4/results.csv" | cut -d, -f16 | grep -cE "^[0-9]+\.[0-9]$")" = 4 ] && grep -q "peer_cpu_s=[0-9.]* (peer pid [0-9]*)" "$OUT_BASE/heavy_4/summary.txt"'
check "1 fake peer was never signalled and still answers" 'curl -s -m 3 http://$PEER_RPC/json_rpc -d "{\"method\":\"get_block_header_by_height\",\"params\":{\"height\":5}}" | grep -q "\"hash\""'
check "1 governor set to performance, then restored to old value" 'grep -q "sudo -n cpupower frequency-set -g performance" "$FAKE_SUDO_LOG" && [ "$(tail -1 "$FAKE_SUDO_LOG")" = "sudo -n cpupower frequency-set -g schedutil" ] && grep -q "governor restored to schedutil" "$SL"'
check "1 our ports are free afterwards" '! ss -ltn | grep -qE ":(38390|38391)\$"'
python3 -I "$KIT/fb_table.py" "$OUT_BASE" > "$W/table.out" 2>&1
check "1 scorer runs on the output; shows peer_cpu_s, 4 dirs, hash 16/16" 'grep -q "peer_cpu_s" "$W/table.out" && grep -q "== heavy_4" "$W/table.out" && grep -q "TOTAL runs=16 hash_match yes=16/16" "$W/table.out"'

# 2. peer whose CPU is not readable: nothing listens on the PEER port -> peer_cpu_s = na; BADHASH; sudo fails; one round
export OUT_BASE=$W/out/bad THREADS=default ROUNDS=1 FAKE_BADHASH=1 PEER=127.0.0.1:38394
: > "$FAKE_SUDO_LOG"
PATH=$W/nosudo:$PATH bash "$KIT/fb_stage.sh" > "$W/bad.out" 2>&1; rc=$?
SL=$OUT_BASE/stage.log
check "2 stage finishes without sudo access" '[ "$rc" = 0 ] && tail -1 "$SL" | grep -qE "^FASTBOX_DONE [0-9]" && grep -q "governor: " "$SL"'
check "2 FAKE_BADHASH=1 records hash_match NO in all 4 runs" '[ "$(cat "$OUT_BASE"/*/results.csv | grep -v ^round | cut -d, -f13 | sort | uniq -c | tr -s " " | tr "\n" ";")" = " 4 NO;" ]'
check "2 peer_cpu_s is na when the peer PID is not found" '[ "$(cat "$OUT_BASE"/*/results.csv | grep -v ^round | cut -d, -f16 | sort -u)" = na ]'
python3 -I "$KIT/fb_table.py" "$OUT_BASE" > "$W/table2.out" 2>&1
check "2 scorer counts hash 0/4 per window and handles na peer cpu" 'grep -q "TOTAL runs=4 hash_match yes=0/4" "$W/table2.out" && ! grep -q Traceback "$W/table2.out"'
unset FAKE_BADHASH; export PEER=127.0.0.1:38393

# 3. refusal to delete a DD without the marker (direct fb_window call)
export DD=$W/dd_nomarker; mkdir -p "$DD"; echo precious > "$DD/important"
SNAP=$SNAP_HEAVY bash "$KIT/fb_window.sh" "$W/out/nomarker" 3105420 30 1 "S|$BIN_S|" > "$W/nomarker.out" 2>&1; rc=$?
check "3 DD without marker: refused, file kept, no node started" '[ "$rc" = 3 ] && [ "$(cat "$DD/important")" = precious ] && grep -q "REFUSE.*marker" "$W/out/nomarker/summary.txt" && [ "$(wc -l < "$W/out/nomarker/results.csv")" = 1 ]'
export DD=$W/dd_main

# 4. refusal when a port is in use (RPC, then P2P)
for port in 38391 38390; do
  python3 -c "
import socket, time
s = socket.socket(); s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1); s.bind(('127.0.0.1', $port)); s.listen(1); time.sleep(60)" &
  lp=$!; PIDS+=($lp); sleep 1
  rm -rf "$DD"
  SNAP=$SNAP_HEAVY bash "$KIT/fb_window.sh" "$W/out/busy$port" 3105420 30 1 "S|$BIN_S|" > "$W/busy$port.out" 2>&1; rc=$?
  check "4 port $port in use: refused before any run, DD not created" '[ "$rc" = 3 ] && grep -q "REFUSE: port $port already has a listener" "$W/out/busy$port/summary.txt" && [ ! -e "$DD" ] && [ "$(wc -l < "$W/out/busy$port/results.csv")" = 1 ] && ! grep -q "^AB_COMPLETE" "$W/out/busy$port/summary.txt"'
  kill "$lp" 2>/dev/null; wait "$lp" 2>/dev/null
done

# 5. missing inputs abort cleanly
export OUT_BASE=$W/out/nobin
BIN_S=$W/bin/does_not_exist bash "$KIT/fb_stage.sh" > "$W/nobin.out" 2>&1; rc=$?
check "5 missing binary: aborts, last line FASTBOX_DONE abort, nothing run" '[ "$rc" != 0 ] && tail -1 "$OUT_BASE/stage.log" | grep -q "^FASTBOX_DONE abort" && [ ! -d "$OUT_BASE/heavy_default" ]'
export OUT_BASE=$W/out/nosnap
SNAP_SMALL=$W/nonexistent bash "$KIT/fb_stage.sh" > "$W/nosnap.out" 2>&1
check "5 missing snapshot: aborts with FASTBOX_DONE abort" 'tail -1 "$OUT_BASE/stage.log" | grep -q "^FASTBOX_DONE abort"'

# 6. process safety: the kit never uses name-matching process killers
check "6 no pkill/killall/pgrep in the kit scripts" '! grep -nE "pkill|killall|pgrep" "$KIT"/fb_window.sh "$KIT"/fb_stage.sh'
check "6 every kill in fb_window.sh targets a PID variable" '! grep -E "\bkill " "$KIT/fb_window.sh" | grep -vE "kill (-0|-TERM|-KILL) \"?\\\$"'
check "6 kit scripts pass bash -n" 'bash -n "$KIT/fb_window.sh" && bash -n "$KIT/fb_stage.sh"'

echo "$pass PASS, $fail FAIL"
[ "$fail" = 0 ]
